SELECT sr.*, u.email as user_email, o.order_no FROM support_requests sr LEFT JOIN users u ON sr.user_id = u.id LEFT JOIN orders o ON sr.order_id = o.id
AND sr.status = #{status}
AND sr.type = #{type}
AND sr.priority = #{priority}
ORDER BY CASE sr.priority WHEN 'URGENT' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'NORMAL' THEN 3 WHEN 'LOW' THEN 4 END ASC, sr.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM support_requests sr


        AND sr.status = #{status}


        AND sr.type = #{type}


        AND sr.priority = #{priority}
